std::vector<int> data = {1, 5, 5, 8, 3, 30};

// 1. Default (Equality Check: Linear Scan)
auto it_eq = std::adjacent_find(data.begin(), data.end());
// it_eq points to the first '5' (data[1])

// 2. Custom Predicate (e.g., a > b)
auto greater_than = [](int a, int b) {
    return a > b;
};

auto it_pred = std::adjacent_find(
    data.begin(), data.end(), greater_than);
// If found, returns iterator to first element of the pair.
// data[3]=8, data[4]=3. it_pred points to '8'.

// If no match found, returns data.end()
